+                // Max
+                if a_plus_5v > b_plus_5v { a_in_v } else { b_in_v }
+            } else if combine_mode == 3 {
+                // Min
+                if channel_a_use && channel_b_use {
+                    if a_plus_5v < b_plus_5v { a_in_v } else { b_in_v }
+                } else if channel_a_use && !channel_b_use {
+                    a_in_v
+                } else if !channel_a_use && channel_b_use {
+                    b_in_v
+                } else {
+                    0
+                }
+            } else if combine_mode == 4 {
