+        if divisor == 1 {
+            (roundf(offset)  * V_PER_OCTAVE) as i16 // whole volt (ie. octave) steps
+        } else {
+            // Continuous offset, quantized by divisor
+            roundf(offset * V_PER_OCTAVE) as i16 / divisor
+        }       
