+                // First channel mute
+                let muted = storage.modify_and_save(|s| {
+                    s.channel_a_mute_saved = !s.channel_a_mute_saved;
+                    s.channel_a_mute_saved
+                });
+                channel_a_mute_glob.set(muted);
+                if muted {
+                    leds.unset(0, Led::Button);
